SELECT t.id, p.diagnosis, (SELECT count(*) FROM laboratory l WHERE l.id=t.id) AS nlab,
 (SELECT count(*) FROM laboratory l WHERE l.id=t.id AND l.plt>100 AND l.plt<400) AS normal_labs
FROM target t JOIN patient p ON p.id=t.id ORDER BY 1

WITH toks AS (
  SELECT p.id, trim(t) AS tok FROM patient p, regexp_split_to_table(p.diagnosis, '[,\x1d]') t WHERE p.diagnosis IS NOT NULL
), sets AS (
  SELECT id, array_agg(DISTINCT tok ORDER BY tok) AS s FROM toks GROUP BY id
), target AS (
  SELECT id FROM sets WHERE s @> ARRAY['RA'] AND s @> ARRAY['SJS'] AND cardinality(s)=2
), flags AS (
  SELECT t.id, EXISTS (SELECT 1 FROM laboratory l WHERE l.id=t.id AND l.plt>100 AND l.plt<400) AS has_normal
  FROM target t
)
SELECT count(*) AS total, count(*) FILTER (WHERE has_normal) AS ever_normal, count(*) FILTER (WHERE NOT has_normal) AS never_normal,
 (SELECT string_agg(DISTINCT p.diagnosis, ' | ') FROM patient p WHERE p.diagnosis ~* 'sjs|sjögren|sjogren' AND p.diagnosis ~* 'ra') AS sample_variants
FROM flags

SELECT count(DISTINCT e.id) exam_ids, count(DISTINCT CASE WHEN e.thrombosis>=1 THEN e.id END) thr_ids,
 count(DISTINCT l.id) lab_ids_in_exam
FROM examination e LEFT JOIN laboratory l ON l.id=e.id;

SELECT p.sex, COUNT(DISTINCT p.id) AS n, 'exact' AS mode FROM patient p JOIN laboratory l ON l.id = p.id WHERE p.diagnosis = 'RA' AND l."un" < 30 GROUP BY p.sex
UNION ALL
SELECT p.sex, COUNT(DISTINCT p.id), 'contains' FROM patient p JOIN laboratory l ON l.id = p.id WHERE p.diagnosis ~ '(^|[^A-Za-z])RA([^A-Za-z]|$)' AND l."un" < 30 GROUP BY p.sex;

