SELECT '[' || p.admission || ']' AS adm, count(DISTINCT p.id) AS patients, count(l.ldh) AS ldh_rows, count(*) FILTER (WHERE l.ldh < 500) AS ldh_normal
FROM patient p LEFT JOIN laboratory l ON l.id = p.id
