WITH plus_atoms AS (
  SELECT a.atom_id, a.element FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = '+'
),
bonded AS (
  SELECT atom_id AS id FROM connected UNION SELECT atom_id2 FROM connected
),
tot AS (SELECT COUNT(*) AS n FROM plus_atoms),
cnt AS (
  SELECT p.element, COUNT(*) AS c FROM plus_atoms p JOIN bonded b ON b.id = p.atom_id GROUP BY p.element
)
SELECT cnt.element, ROUND(100.0 * (SELECT COUNT(*) FROM plus_atoms pa WHERE pa.element = cnt.element) / (SELECT n FROM tot), 2) AS pct_of_all_plus_atoms
FROM cnt
WHERE cnt.c = (SELECT MAX(c) FROM cnt);

