WITH plus_atoms AS (
  SELECT a.atom_id, a.element FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = '+'
),
bonded AS (
  SELECT atom_id AS aid FROM connected UNION SELECT atom_id2 FROM connected
),
